INSERT INTO public.findings (id, user_id, scan_id, type, severity, title, description, file, line, column_index, code, rule_id, rule_name, cve, package, installed_version, fixed_version, cvss_score, cwe, reference_urls, remediation, status, created_at, updated_at) VALUES
  ('4338c095-8ea2-4813-8a83-1885ef08242c', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'e182caac-03d4-4f21-8230-35d7f08b3e00', 'vulnerability', 'medium', 'CVE-2026-16729', 'undici''s setCookie function does not fully sanitize cookie attributes. In undici before 6.28.0, from 7.0.0 up to before 7.29.0, and from 8.0.0 up to before 8.9.0, a domain value is not checked for semicolons and entries in the unparsed array are not sanitized, so attacker-influenced input can inject additional cookie attributes. For example, a domain value containing a semicolon can append attributes such as SameSite, and an unparsed entry can inject attributes such as HttpOnly, without the caller setting them. Applications that pass user-controlled input to these fields, such as multi-tenant or reverse-proxy servers that scope session cookies to a tenant-supplied domain, can have SameSite CSRF protections bypassed, or the Secure, HttpOnly, and SameSite attributes forced, stripped, or overridden. The issue is fixed in undici 6.28.0, 7.29.0, and 8.9.0.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-16729', NULL, 'CVE-2026-16729', 'undici', '7.28.0', '6.28.0, 7.29.0, 8.9.0', 6.5, 'CWE-74', '["https://access.redhat.com/security/cve/CVE-2026-16729","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/10d93fc332f2c8c161982dec3833201de29891b5","https://github.com/nodejs/undici/commit/3bf91ddb493e853957f3a58e155326a668ab8aef","https://github.com/nodejs/undici/commit/af7484043ee075a6f216da0ad77e1dac55199235","https://github.com/nodejs/undici/releases/tag/v6.28.0","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-v3r7-h72x-cjcm","https://nvd.nist.gov/vuln/detail/CVE-2026-16729","https://www.cve.org/CVERecord?id=CVE-2026-16729"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade undici to 6.28.0, 7.29.0, 8.9.0"}', 'open', to_timestamp(1787723453780 / 1000.0), to_timestamp(1787723453780 / 1000.0)),
  ('c4680e22-115d-4b10-9e5a-6c5199967d69', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'e182caac-03d4-4f21-8230-35d7f08b3e00', 'vulnerability', 'high', 'CVE-2026-55553', 'urllib is an HTTP client for Node.js that supports authentication, redirects, timeouts, and other request features. Prior to 4.9.1 and 2.44.1, urllib follows redirects through followRedirect but reuses caller-supplied options across origins. In src/HttpClient.ts, #requestInternal recursively calls this.#requestInternal(nextUrl.href, options, requestContext), causing options.headers and auth or digestAuth values to be reused when the redirect target has a different scheme, host, or port. Authorization, Cookie, Proxy-Authorization, x-api-key, x-auth-token, and x-access-token can therefore be sent to an attacker-controlled redirected origin, exposing credentials intended for the original origin and potentially allowing reuse against the original partner API or related services. No user interaction is required. This issue is fixed in versions 2.44.1 and 4.9.1.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-55553', NULL, 'CVE-2026-55553', 'urllib', '4.9.0', '4.9.1, 2.44.1', NULL, 'CWE-200', '["https://github.com/node-modules/urllib","https://github.com/node-modules/urllib/commit/7c86c465883ebd3dea5109c87d7bbe3b00960a16","https://github.com/node-modules/urllib/commit/811a8d56e64e540bf6a19bf8b3737692f05d5c46","https://github.com/node-modules/urllib/pull/812","https://github.com/node-modules/urllib/pull/813","https://github.com/node-modules/urllib/releases/tag/v2.44.1","https://github.com/node-modules/urllib/releases/tag/v4.9.1","https://github.com/node-modules/urllib/security/advisories/GHSA-hq3h-g68c-hp78"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade urllib to 4.9.1, 2.44.1"}', 'open', to_timestamp(1787723453780 / 1000.0), to_timestamp(1787723453780 / 1000.0)),
  ('74bdbfe2-7cff-4a77-9b7f-52a0f8c1e7a5', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'security_issue', 'info', 'GitHub Actions step uses a mutable tag or branch reference. Tags and branch names can be silently repointed by the action owner, enabling supply-chain attacks — as seen in the trivy-action and kics-github-action compromises. Pin the reference to a full 40-character commit SHA instead, e.g. `uses: actions/checkout@8ade135a41bc03ea155e62e844d188df1ea18608`.', 'GitHub Actions step uses a mutable tag or branch reference. Tags and branch names can be silently repointed by the action owner, enabling supply-chain attacks — as seen in the trivy-action and kics-github-action compromises. Pin the reference to a full 40-character commit SHA instead, e.g. `uses: actions/checkout@8ade135a41bc03ea155e62e844d188df1ea18608`.', '/var/folders/hm/p23mppcx3tbd4zg7k16dt67w0000gr/T/github-scan-amJgVJ/repo/.github/workflows/publish-style-skill.yml', 19, 9, NULL, 'yaml.github-actions.security.github-actions-mutable-action-tag.github-actions-mutable-action-tag', NULL, NULL, NULL, NULL, NULL, NULL, 'CWE-1357: Reliance on Insufficiently Trustworthy Component', '["https://docs.github.com/en/actions/security-guides/security-hardening-for-github-actions#using-third-party-actions"]'::jsonb, NULL, 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('ba60ab65-ed8c-4379-b66f-d9f370b72480', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'security_issue', 'info', 'GitHub Actions step uses a mutable tag or branch reference. Tags and branch names can be silently repointed by the action owner, enabling supply-chain attacks — as seen in the trivy-action and kics-github-action compromises. Pin the reference to a full 40-character commit SHA instead, e.g. `uses: actions/checkout@8ade135a41bc03ea155e62e844d188df1ea18608`.', 'GitHub Actions step uses a mutable tag or branch reference. Tags and branch names can be silently repointed by the action owner, enabling supply-chain attacks — as seen in the trivy-action and kics-github-action compromises. Pin the reference to a full 40-character commit SHA instead, e.g. `uses: actions/checkout@8ade135a41bc03ea155e62e844d188df1ea18608`.', '/var/folders/hm/p23mppcx3tbd4zg7k16dt67w0000gr/T/github-scan-amJgVJ/repo/.github/workflows/publish-style-skill.yml', 22, 9, NULL, 'yaml.github-actions.security.github-actions-mutable-action-tag.github-actions-mutable-action-tag', NULL, NULL, NULL, NULL, NULL, NULL, 'CWE-1357: Reliance on Insufficiently Trustworthy Component', '["https://docs.github.com/en/actions/security-guides/security-hardening-for-github-actions#using-third-party-actions"]'::jsonb, NULL, 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('a3ec2f1c-2e48-4889-a082-58f9dfb0c578', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'security_issue', 'info', 'Detected a call to `replaceAll()` in an attempt to HTML escape the string `String(value || '''')`. Manually sanitizing input through a manually built list can be circumvented in many situations, and it''s better to use a well known sanitization library such as `sanitize-html` or `DOMPurify`.', 'Detected a call to `replaceAll()` in an attempt to HTML escape the string `String(value || '''')`. Manually sanitizing input through a manually built list can be circumvented in many situations, and it''s better to use a well known sanitization library such as `sanitize-html` or `DOMPurify`.', '/var/folders/hm/p23mppcx3tbd4zg7k16dt67w0000gr/T/github-scan-amJgVJ/repo/scripts/alipay-webpay-sandbox-server.mjs', 18, 10, NULL, 'javascript.audit.detect-replaceall-sanitization.detect-replaceall-sanitization', NULL, NULL, NULL, NULL, NULL, NULL, 'CWE-79: Improper Neutralization of Input During Web Page Generation (''Cross-site Scripting'')', '["https://www.npmjs.com/package/dompurify","https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html"]'::jsonb, NULL, 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('d08d4801-98e1-432e-973d-045cb366c167', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'security_issue', 'info', 'Cannot determine what ''safeId'' is and it is used with a ''<script>'' tag. This could be susceptible to cross-site scripting (XSS). Ensure ''safeId'' is not externally controlled, or sanitize this data.', 'Cannot determine what ''safeId'' is and it is used with a ''<script>'' tag. This could be susceptible to cross-site scripting (XSS). Ensure ''safeId'' is not externally controlled, or sanitize this data.', '/var/folders/hm/p23mppcx3tbd4zg7k16dt67w0000gr/T/github-scan-amJgVJ/repo/scripts/alipay-webpay-sandbox-server.mjs', 95, 16, NULL, 'javascript.lang.security.audit.unknown-value-with-script-tag.unknown-value-with-script-tag', NULL, NULL, NULL, NULL, NULL, NULL, 'CWE-79: Improper Neutralization of Input During Web Page Generation (''Cross-site Scripting'')', '["https://www.developsec.com/2017/11/09/xss-in-a-script-tag/","https://github.com/juice-shop/juice-shop/blob/1ceb8751e986dacd3214a618c37e7411be6bc11a/routes/videoHandler.ts#L68"]'::jsonb, NULL, 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('1b183e34-d85a-4041-b736-3c79de3b0df8', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'high', 'CVE-2026-14257', 'brace-expansion through 5.0.7 is vulnerable to denial of service via memory exhaustion. The expand() function limits the number of results with a max option (default 100,000) but does not bound the length of each result string. By chaining multiple brace groups, an attacker keeps the result count under the limit while making each result progressively longer, so total memory scales with both count and string length until the process hits a fatal, uncatchable out-of-memory error. About 7.5 KB of input (''{a,b}''.repeat(1500)) crashes a default Node.js process. Any application that passes attacker-influenced strings to brace-expansion.expand() - directly or transitively via minimatch / glob brace patterns - can be crashed by a small request. Fixed in 5.0.8 by adding a maxLength option (default 4,000,000) that bounds accumulated output and intermediate arrays.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-14257', NULL, 'CVE-2026-14257', 'brace-expansion', '2.1.2', '5.0.8, 3.0.3, 2.1.3, 1.1.17', NULL, 'CWE-400', '["https://access.redhat.com/errata/RHSA-2026:55541","https://access.redhat.com/errata/RHSA-2026:58819","https://access.redhat.com/security/cve/CVE-2026-14257","https://bugzilla.redhat.com/2506433","https://bugzilla.redhat.com/2507593","https://bugzilla.redhat.com/2510722","https://bugzilla.redhat.com/2510801","https://bugzilla.redhat.com/show_bug.cgi?id=2506433","https://bugzilla.redhat.com/show_bug.cgi?id=2510722","https://bugzilla.redhat.com/show_bug.cgi?id=2510801","https://creativecommons.org/licenses/by/4.0/","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-14257","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-69152","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-69192","https://errata.almalinux.org/10/ALSA-2026-58819.html","https://errata.rockylinux.org/RLSA-2026:55541","https://github.com/juliangruber/brace-expansion","https://github.com/juliangruber/brace-expansion/commit/139d015104e71433ad52a41d19467c48ecbb2c7d","https://github.com/juliangruber/brace-expansion/commit/a1bd33999ea75262c4749fff3bbb0d1372bd07b5","https://github.com/juliangruber/brace-expansion/commit/cb4b9e47cc2ec777c14b2b4492fb431a56f6a031","https://github.com/juliangruber/brace-expansion/commit/d13ff455a58b0d56704f0111e3c2a0b16ceb06eb","https://github.com/juliangruber/brace-expansion/pull/129","https://github.com/juliangruber/brace-expansion/pull/130","https://github.com/juliangruber/brace-expansion/pull/136","https://github.com/juliangruber/brace-expansion/security/advisories/GHSA-mh99-v99m-4gvg","https://linux.oracle.com/cve/CVE-2026-14257.html","https://linux.oracle.com/errata/ELSA-2026-55603.html","https://nvd.nist.gov/vuln/detail/CVE-2026-14257","https://www.cve.org/CVERecord?id=CVE-2026-14257","https://www.npmjs.com/package/brace-expansion"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade brace-expansion to 5.0.8, 3.0.3, 2.1.3, 1.1.17"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('800a4f45-2606-44b0-be82-1839d2719c82', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'high', 'CVE-2026-69152', 'The brace-expansion library generates arbitrary strings containing a common prefix and suffix. Prior to 1.1.18, 2.1.4, 3.0.6, and 5.0.9, expand() does not apply maxLength while constructing comma-alternative intermediate arrays or padded sequences, allowing attacker-controlled input to exhaust memory or block the event loop. The fix for CVE-2026-14257 is bypassed by the vulnerability. This issue is fixed in versions 1.1.18, 2.1.4, 3.0.6, and 5.0.9.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-69152', NULL, 'CVE-2026-69152', 'brace-expansion', '2.1.2', '1.1.18, 2.1.4, 3.0.6, 5.0.9', NULL, 'CWE-400', '["https://access.redhat.com/errata/RHSA-2026:55541","https://access.redhat.com/errata/RHSA-2026:58819","https://access.redhat.com/security/cve/CVE-2026-69152","https://bugzilla.redhat.com/2506433","https://bugzilla.redhat.com/2507593","https://bugzilla.redhat.com/2510722","https://bugzilla.redhat.com/2510801","https://bugzilla.redhat.com/show_bug.cgi?id=2506433","https://bugzilla.redhat.com/show_bug.cgi?id=2510722","https://bugzilla.redhat.com/show_bug.cgi?id=2510801","https://creativecommons.org/licenses/by/4.0/","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-14257","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-69152","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-69192","https://errata.almalinux.org/10/ALSA-2026-58819.html","https://errata.rockylinux.org/RLSA-2026:55541","https://github.com/juliangruber/brace-expansion","https://github.com/juliangruber/brace-expansion/commit/139d015104e71433ad52a41d19467c48ecbb2c7d","https://github.com/juliangruber/brace-expansion/commit/1e30c930238d7162802d88a94189182def178dac","https://github.com/juliangruber/brace-expansion/commit/688a99eeaab02627c2b89ba8ba4821fecfa659cf","https://github.com/juliangruber/brace-expansion/commit/cb4b9e47cc2ec777c14b2b4492fb431a56f6a031","https://github.com/juliangruber/brace-expansion/security/advisories/GHSA-rgw5-rvv9-x895","https://linux.oracle.com/cve/CVE-2026-69152.html","https://linux.oracle.com/errata/ELSA-2026-55603.html","https://nvd.nist.gov/vuln/detail/CVE-2026-69152","https://www.cve.org/CVERecord?id=CVE-2026-69152"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade brace-expansion to 1.1.18, 2.1.4, 3.0.6, 5.0.9"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('1a3a0908-86e7-4b68-a9ac-35e19e57d701', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'high', 'CVE-2026-67213', 'nanoid (Nano ID) before 5.1.6 contains an infinite loop in the customAlphabet and customRandom functions. When these functions are configured with a size of 0, the internal generation loop never satisfies its exit condition and spins indefinitely, hanging the calling thread. An application that passes an unvalidated, attacker-controlled size of 0 to these functions is exposed to a denial-of-service condition.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-67213', NULL, 'CVE-2026-67213', 'nanoid', '3.3.12', '3.3.18, 5.1.6', 7.5, 'CWE-835', '["https://access.redhat.com/security/cve/CVE-2026-67213","https://github.com/ai/nanoid","https://github.com/ai/nanoid/commit/cb3626d0f3342fdf179cd425fd9c4fbb92c7d0e7","https://github.com/ai/nanoid/commit/e10f8d40ce9d1ab47f66d65a16b48086432730d0","https://github.com/ai/nanoid/commit/f9d13f150847d117877adee3460a46eceb0cf49b","https://github.com/ai/nanoid/releases/tag/3.3.17","https://github.com/ai/nanoid/releases/tag/3.3.18","https://github.com/ai/nanoid/releases/tag/5.1.6","https://nvd.nist.gov/vuln/detail/CVE-2026-67213","https://www.cve.org/CVERecord?id=CVE-2026-67213","https://www.vulncheck.com/advisories/nanoid-before-infinite-loop-via-zero-size-in-customalphabet-and-customrandom"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade nanoid to 3.3.18, 5.1.6"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('1d72d7d8-e987-4c25-8925-0d81e0bcf94c', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'high', 'CVE-2026-67214', 'nanoid (Nano ID) before 3.3.16 and 5.1.16 contains an infinite loop in the customAlphabet and nanoid functions of its non-secure module (nanoid/non-secure). When these functions are given a negative size, the loop counter is decremented from a negative value and never reaches its termination condition, spinning indefinitely and hanging the calling thread. An application that passes an unvalidated, attacker-controlled negative size to these functions is exposed to a denial-of-service condition.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-67214', NULL, 'CVE-2026-67214', 'nanoid', '3.3.12', '3.3.16, 5.1.16', 7.5, 'CWE-835', '["https://access.redhat.com/security/cve/CVE-2026-67214","https://github.com/ai/nanoid","https://github.com/ai/nanoid/commit/6ccc67bbaba71d3d77a21d9b636f4171a268ce49","https://github.com/ai/nanoid/commit/e835c9b71eab832bc6106944bdd26ea96cf2c66d","https://github.com/ai/nanoid/pull/600","https://github.com/ai/nanoid/pull/601","https://github.com/ai/nanoid/releases/tag/3.3.16","https://github.com/ai/nanoid/releases/tag/5.1.16","https://nvd.nist.gov/vuln/detail/CVE-2026-67214","https://www.cve.org/CVERecord?id=CVE-2026-67214","https://www.vulncheck.com/advisories/nanoid-before-infinite-loop-via-negative-size-in-non-secure-module"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade nanoid to 3.3.16, 5.1.16"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('01001eb5-5530-4a63-a8bb-08369041566d', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'high', 'CVE-2026-73646', 'PostCSS takes a CSS file and provides an API to analyze and modify its rules by transforming the rules into an Abstract Syntax Tree. Prior to 8.5.18, lib/previous-map.js loadMap() passes attacker-controlled sourceMappingURL values to join(dirname(opts.from), annotation), and loadFile() permits traversed or absolute .map paths, allowing untrusted CSS processed without map: false to disclose sourcesContent from arbitrary reachable .map files through result.map. This issue is fixed in version 8.5.18.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-73646', NULL, 'CVE-2026-73646', 'postcss', '8.5.13', '8.5.18', NULL, 'CWE-22', '["https://github.com/postcss/postcss","https://github.com/postcss/postcss/commit/95663d3eb7ba26f4854dd19d3b4f4425760cf56c","https://github.com/postcss/postcss/releases/tag/8.5.18","https://github.com/postcss/postcss/security/advisories/GHSA-r28c-9q8g-f849"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade postcss to 8.5.18"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('d39f2bfa-a05a-4299-b688-10666a9a3ba0', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'medium', 'CVE-2026-69153', 'PostCSS takes a CSS file and provides an API to analyze and modify its rules by transforming the rules into an Abstract Syntax Tree. Prior to 8.5.19, if from is unset, an attacker can cause PreviousMap.loadFile() to read an unintended source-map file by supplying an absolute or directory-traversal sourceMappingURL. The resulting map’s sources and sourcesContent may then be exposed to the application. This issue is fixed in version 8.5.19.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-69153', NULL, 'CVE-2026-69153', 'postcss', '8.5.13', '8.5.23', 5.3, 'CWE-22', '["https://access.redhat.com/security/cve/CVE-2026-69153","https://github.com/postcss/postcss","https://github.com/postcss/postcss/commit/7beca139e70f9075c6b19700fcb00dd8033e5da8","https://github.com/postcss/postcss/releases/tag/8.5.19","https://github.com/postcss/postcss/security/advisories/GHSA-fxqj-rqcc-2cmp","https://nvd.nist.gov/vuln/detail/CVE-2026-69153","https://www.cve.org/CVERecord?id=CVE-2026-69153"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade postcss to 8.5.23"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('f36742d9-5587-4da2-9759-c56f7d5608dc', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'high', 'CVE-2026-13697', 'undici''s cache interceptor mishandles malformed Cache-Control private directives. In undici 7.0.0 up to before 7.29.0 and 8.0.0 up to before 8.9.0, a response carrying a degenerate qualified private directive, such as private set to an empty value, can be stored in the default shared cache and later served to a different caller with the same cache key, disclosing private response bodies and headers including Set-Cookie. Separately, a Cache-Control header that combines an unqualified private directive with a qualified one triggers an uncaught TypeError in the cache-control parser, which rejects the request and, depending on the consumer''s error handling, can terminate the process. Both issues affect applications using the cache interceptor in shared mode, including the default configuration. The issues are fixed in undici 7.29.0 and 8.9.0.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-13697', NULL, 'CVE-2026-13697', 'undici', '7.28.0', '7.29.0, 8.9.0', 9.1, 'CWE-200', '["https://access.redhat.com/security/cve/CVE-2026-13697","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/4fe5bc5fefe5ac81a200fc8e1cf84b8bf8464451","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-4cwx-7wf7-3272","https://nvd.nist.gov/vuln/detail/CVE-2026-13697","https://www.cve.org/CVERecord?id=CVE-2026-13697"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade undici to 7.29.0, 8.9.0"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('be8ed8da-2f50-4a86-8d2f-f9b0919e5cbd', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'medium', 'CVE-2026-14643', 'undici''s cache interceptor mishandles optional whitespace placed around the equals sign of a qualified no-cache or private Cache-Control directive. In undici from 7.0.0 up to before 7.29.0 and from 8.0.0 up to before 8.9.0, the parser either drops the directive or stores a field name with literal quote characters, so the cache decision fails to recognize the qualification and the response is stored. In shared-cache mode, this lets a response containing one user''s authenticated data be served from cache to a later caller, including an unauthenticated one, when both requests resolve to the same cache key. It affects applications that enable the cache interceptor in shared mode, forward Authorization headers upstream, and receive cacheable responses with qualified directives padded with whitespace around the equals sign. This is the whitespace-around-equals variant that the fix for CVE-2026-9678 did not normalize, and it is fixed in undici 7.29.0 and 8.9.0.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-14643', NULL, 'CVE-2026-14643', 'undici', '7.28.0', '7.29.0, 8.9.0', 7.5, 'CWE-436', '["https://access.redhat.com/security/cve/CVE-2026-14643","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/85a240551c9feb8b8a0ecc56c84b2b3015add8a9","https://github.com/nodejs/undici/commit/cb105d7c79069150982fa11acada0dd94a60dbbc","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-jr45-8vmc-qm54","https://nvd.nist.gov/vuln/detail/CVE-2026-14643","https://www.cve.org/CVERecord?id=CVE-2026-14643"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade undici to 7.29.0, 8.9.0"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('284bb221-552c-483c-8639-9c4966e1d070', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'medium', 'CVE-2026-15157', 'undici does not validate the type property of a duck-typed blob-like request body before using it as the Content-Type header on the HTTP/1.1 dispatcher. In undici before 6.28.0, from 7.0.0 up to before 7.29.0, and from 8.0.0 up to before 8.9.0, an application that passes a hand-rolled blob-like body (via request, stream, pipeline, or dispatch) whose type is derived from untrusted input allows an attacker to inject CRLF sequences and append arbitrary HTTP headers, potentially smuggling a second request past the upstream. Native Blob objects are safe because their constructor strips CRLF from the type, and fetch is unaffected because it validates headers, but ecosystem libraries that build duck-typed blob shapes from user input can reach the vulnerable path. This is the same defect class as CVE-2022-35948 and CVE-2026-1527, on a header sink that the earlier fixes did not cover. The issue is fixed in undici 6.28.0, 7.29.0, and 8.9.0.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-15157', NULL, 'CVE-2026-15157', 'undici', '7.28.0', '6.28.0, 7.29.0, 8.9.0', 5.4, 'CWE-93', '["https://access.redhat.com/security/cve/CVE-2026-15157","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/33928bc24f742ea8422ed90d17f2e0cc83e4d09d","https://github.com/nodejs/undici/commit/740a0b7c173cb4a83a5b693e96e8f3a116cfc400","https://github.com/nodejs/undici/commit/7d3cf924c262c486bc77f951348f4e5c847b7b42","https://github.com/nodejs/undici/releases/tag/v6.28.0","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-m8rv-5g2x-5cg5","https://nvd.nist.gov/vuln/detail/CVE-2026-15157","https://www.cve.org/CVERecord?id=CVE-2026-15157"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade undici to 6.28.0, 7.29.0, 8.9.0"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('a3271c48-2f59-44b0-8af3-6bcc0ae76f6f', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'medium', 'CVE-2026-16728', 'undici''s retry interceptor can deliver a response whose body length does not match the Content-Length header exposed to the application after a retry or resume of a partial response. In undici before 6.28.0, from 7.0.0 up to before 7.29.0, and from 8.0.0 up to before 8.9.0, a malicious or faulty upstream can return a partial response with a mismatched framing header, close the socket early, and have the retry interceptor assemble a body of a different length while the original Content-Length stays attached. Applications that use the retry interceptor and forward upstream headers and bodies downstream, such as proxies or gateways, may then emit an invalid HTTP response with a stale Content-Length, leading to downstream response desynchronization, connection hangs, or response corruption. Exploitation requires the retry interceptor enabled, an upstream returning a mismatched partial response, and a downstream forwarder that does not remove or recalculate Content-Length. The issue is fixed in undici 6.28.0, 7.29.0, and 8.9.0.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-16728', NULL, 'CVE-2026-16728', 'undici', '7.28.0', '6.28.0, 7.29.0, 8.9.0', 6.5, 'CWE-444', '["https://access.redhat.com/security/cve/CVE-2026-16728","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/1b5a5312c3a7d7a30c31bf0d000b39a8a2531e1c","https://github.com/nodejs/undici/commit/2b3f749336d356bbbc50192f87f6cf7bc714721a","https://github.com/nodejs/undici/commit/4a9dafb16ff43880cf590e6d9c2aeee25fbff6d7","https://github.com/nodejs/undici/commit/4fd5a0c61e627f928b7003adc4ffe1e55ec63420","https://github.com/nodejs/undici/commit/cba3a52ac2e7abcc4e656d82af8579ea82c2bb9e","https://github.com/nodejs/undici/commit/e11a68ed4ff345c79402476f7a00d473443e318d","https://github.com/nodejs/undici/releases/tag/v6.28.0","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-8xcm-r25x-g524","https://hackerone.com/reports/3828685","https://nvd.nist.gov/vuln/detail/CVE-2026-16728","https://www.cve.org/CVERecord?id=CVE-2026-16728"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade undici to 6.28.0, 7.29.0, 8.9.0"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('43abf8cf-ef93-438d-a3e5-41c92bae6ead', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'medium', 'CVE-2026-16729', 'undici''s setCookie function does not fully sanitize cookie attributes. In undici before 6.28.0, from 7.0.0 up to before 7.29.0, and from 8.0.0 up to before 8.9.0, a domain value is not checked for semicolons and entries in the unparsed array are not sanitized, so attacker-influenced input can inject additional cookie attributes. For example, a domain value containing a semicolon can append attributes such as SameSite, and an unparsed entry can inject attributes such as HttpOnly, without the caller setting them. Applications that pass user-controlled input to these fields, such as multi-tenant or reverse-proxy servers that scope session cookies to a tenant-supplied domain, can have SameSite CSRF protections bypassed, or the Secure, HttpOnly, and SameSite attributes forced, stripped, or overridden. The issue is fixed in undici 6.28.0, 7.29.0, and 8.9.0.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-16729', NULL, 'CVE-2026-16729', 'undici', '7.28.0', '6.28.0, 7.29.0, 8.9.0', 6.5, 'CWE-74', '["https://access.redhat.com/security/cve/CVE-2026-16729","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/10d93fc332f2c8c161982dec3833201de29891b5","https://github.com/nodejs/undici/commit/3bf91ddb493e853957f3a58e155326a668ab8aef","https://github.com/nodejs/undici/commit/af7484043ee075a6f216da0ad77e1dac55199235","https://github.com/nodejs/undici/releases/tag/v6.28.0","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-v3r7-h72x-cjcm","https://nvd.nist.gov/vuln/detail/CVE-2026-16729","https://www.cve.org/CVERecord?id=CVE-2026-16729"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade undici to 6.28.0, 7.29.0, 8.9.0"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('258f131a-9a0a-4961-a3f6-a44708907681', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b74251b2-64ec-44ed-96df-873d33aac598', 'vulnerability', 'high', 'CVE-2026-55553', 'urllib is an HTTP client for Node.js that supports authentication, redirects, timeouts, and other request features. Prior to 4.9.1 and 2.44.1, urllib follows redirects through followRedirect but reuses caller-supplied options across origins. In src/HttpClient.ts, #requestInternal recursively calls this.#requestInternal(nextUrl.href, options, requestContext), causing options.headers and auth or digestAuth values to be reused when the redirect target has a different scheme, host, or port. Authorization, Cookie, Proxy-Authorization, x-api-key, x-auth-token, and x-access-token can therefore be sent to an attacker-controlled redirected origin, exposing credentials intended for the original origin and potentially allowing reuse against the original partner API or related services. No user interaction is required. This issue is fixed in versions 2.44.1 and 4.9.1.', 'package-lock.json', 1, NULL, NULL, 'CVE-2026-55553', NULL, 'CVE-2026-55553', 'urllib', '4.9.0', '4.9.1, 2.44.1', NULL, 'CWE-200', '["https://github.com/node-modules/urllib","https://github.com/node-modules/urllib/commit/7c86c465883ebd3dea5109c87d7bbe3b00960a16","https://github.com/node-modules/urllib/commit/811a8d56e64e540bf6a19bf8b3737692f05d5c46","https://github.com/node-modules/urllib/pull/812","https://github.com/node-modules/urllib/pull/813","https://github.com/node-modules/urllib/releases/tag/v2.44.1","https://github.com/node-modules/urllib/releases/tag/v4.9.1","https://github.com/node-modules/urllib/security/advisories/GHSA-hq3h-g68c-hp78"]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade urllib to 4.9.1, 2.44.1"}', 'open', to_timestamp(1787725915102 / 1000.0), to_timestamp(1787725915102 / 1000.0)),
  ('11f0dc6e-6b15-4d60-94dc-75f5932448b2', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'high', 'CVE-2026-14257', 'brace-expansion through 5.0.7 is vulnerable to denial of service via memory exhaustion. The expand() function limits the number of results with a max option (default 100,000) but does not bound the length of each result string. By chaining multiple brace groups, an attacker keeps the result count under the limit while making each result progressively longer, so total memory scales with both count and string length until the process hits a fatal, uncatchable out-of-memory error. About 7.5 KB of input (''{a,b}''.repeat(1500)) crashes a default Node.js process. Any application that passes attacker-influenced strings to brace-expansion.expand() - directly or transitively via minimatch / glob brace patterns - can be crashed by a small request. Fixed in 5.0.8 by adding a maxLength option (default 4,000,000) that bounds accumulated output and intermediate arrays.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-14257', NULL, 'CVE-2026-14257', 'brace-expansion', '2.1.2', '5.0.8, 3.0.3, 2.1.3, 1.1.17', NULL, 'CWE-400', '["https://access.redhat.com/errata/RHSA-2026:55541","https://access.redhat.com/errata/RHSA-2026:58819","https://access.redhat.com/security/cve/CVE-2026-14257","https://bugzilla.redhat.com/2506433","https://bugzilla.redhat.com/2507593","https://bugzilla.redhat.com/2510722","https://bugzilla.redhat.com/2510801","https://bugzilla.redhat.com/show_bug.cgi?id=2506433","https://bugzilla.redhat.com/show_bug.cgi?id=2510722","https://bugzilla.redhat.com/show_bug.cgi?id=2510801","https://creativecommons.org/licenses/by/4.0/","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-14257","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-69152","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-69192","https://errata.almalinux.org/10/ALSA-2026-58819.html","https://errata.rockylinux.org/RLSA-2026:55541","https://github.com/juliangruber/brace-expansion","https://github.com/juliangruber/brace-expansion/commit/139d015104e71433ad52a41d19467c48ecbb2c7d","https://github.com/juliangruber/brace-expansion/commit/a1bd33999ea75262c4749fff3bbb0d1372bd07b5","https://github.com/juliangruber/brace-expansion/commit/cb4b9e47cc2ec777c14b2b4492fb431a56f6a031","https://github.com/juliangruber/brace-expansion/commit/d13ff455a58b0d56704f0111e3c2a0b16ceb06eb","https://github.com/juliangruber/brace-expansion/pull/129","https://github.com/juliangruber/brace-expansion/pull/130","https://github.com/juliangruber/brace-expansion/pull/136","https://github.com/juliangruber/brace-expansion/security/advisories/GHSA-mh99-v99m-4gvg","https://linux.oracle.com/cve/CVE-2026-14257.html","https://linux.oracle.com/errata/ELSA-2026-55603.html","https://nvd.nist.gov/vuln/detail/CVE-2026-14257","https://www.cve.org/CVERecord?id=CVE-2026-14257","https://www.npmjs.com/package/brace-expansion"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('69509598-bd6c-4c63-ac7b-40e4db6b4886', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'high', 'CVE-2026-69152', 'The brace-expansion library generates arbitrary strings containing a common prefix and suffix. Prior to 1.1.18, 2.1.4, 3.0.6, and 5.0.9, expand() does not apply maxLength while constructing comma-alternative intermediate arrays or padded sequences, allowing attacker-controlled input to exhaust memory or block the event loop. The fix for CVE-2026-14257 is bypassed by the vulnerability. This issue is fixed in versions 1.1.18, 2.1.4, 3.0.6, and 5.0.9.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-69152', NULL, 'CVE-2026-69152', 'brace-expansion', '2.1.2', '1.1.18, 2.1.4, 3.0.6, 5.0.9', NULL, 'CWE-400', '["https://access.redhat.com/errata/RHSA-2026:55541","https://access.redhat.com/errata/RHSA-2026:58819","https://access.redhat.com/security/cve/CVE-2026-69152","https://bugzilla.redhat.com/2506433","https://bugzilla.redhat.com/2507593","https://bugzilla.redhat.com/2510722","https://bugzilla.redhat.com/2510801","https://bugzilla.redhat.com/show_bug.cgi?id=2506433","https://bugzilla.redhat.com/show_bug.cgi?id=2510722","https://bugzilla.redhat.com/show_bug.cgi?id=2510801","https://creativecommons.org/licenses/by/4.0/","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-14257","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-69152","https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2026-69192","https://errata.almalinux.org/10/ALSA-2026-58819.html","https://errata.rockylinux.org/RLSA-2026:55541","https://github.com/juliangruber/brace-expansion","https://github.com/juliangruber/brace-expansion/commit/139d015104e71433ad52a41d19467c48ecbb2c7d","https://github.com/juliangruber/brace-expansion/commit/1e30c930238d7162802d88a94189182def178dac","https://github.com/juliangruber/brace-expansion/commit/688a99eeaab02627c2b89ba8ba4821fecfa659cf","https://github.com/juliangruber/brace-expansion/commit/cb4b9e47cc2ec777c14b2b4492fb431a56f6a031","https://github.com/juliangruber/brace-expansion/security/advisories/GHSA-rgw5-rvv9-x895","https://linux.oracle.com/cve/CVE-2026-69152.html","https://linux.oracle.com/errata/ELSA-2026-55603.html","https://nvd.nist.gov/vuln/detail/CVE-2026-69152","https://www.cve.org/CVERecord?id=CVE-2026-69152"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('80aa079b-614d-4e92-8be1-de67e7e42e12', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'high', 'CVE-2026-67213', 'nanoid (Nano ID) before 5.1.6 contains an infinite loop in the customAlphabet and customRandom functions. When these functions are configured with a size of 0, the internal generation loop never satisfies its exit condition and spins indefinitely, hanging the calling thread. An application that passes an unvalidated, attacker-controlled size of 0 to these functions is exposed to a denial-of-service condition.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-67213', NULL, 'CVE-2026-67213', 'nanoid', '3.3.12', '3.3.18, 5.1.6', 7.5, 'CWE-835', '["https://access.redhat.com/security/cve/CVE-2026-67213","https://github.com/ai/nanoid","https://github.com/ai/nanoid/commit/cb3626d0f3342fdf179cd425fd9c4fbb92c7d0e7","https://github.com/ai/nanoid/commit/e10f8d40ce9d1ab47f66d65a16b48086432730d0","https://github.com/ai/nanoid/commit/f9d13f150847d117877adee3460a46eceb0cf49b","https://github.com/ai/nanoid/releases/tag/3.3.17","https://github.com/ai/nanoid/releases/tag/3.3.18","https://github.com/ai/nanoid/releases/tag/5.1.6","https://nvd.nist.gov/vuln/detail/CVE-2026-67213","https://www.cve.org/CVERecord?id=CVE-2026-67213","https://www.vulncheck.com/advisories/nanoid-before-infinite-loop-via-zero-size-in-customalphabet-and-customrandom"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('0891400a-f6aa-4f35-9e96-ee57320d1be6', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'high', 'CVE-2026-67214', 'nanoid (Nano ID) before 3.3.16 and 5.1.16 contains an infinite loop in the customAlphabet and nanoid functions of its non-secure module (nanoid/non-secure). When these functions are given a negative size, the loop counter is decremented from a negative value and never reaches its termination condition, spinning indefinitely and hanging the calling thread. An application that passes an unvalidated, attacker-controlled negative size to these functions is exposed to a denial-of-service condition.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-67214', NULL, 'CVE-2026-67214', 'nanoid', '3.3.12', '3.3.16, 5.1.16', 7.5, 'CWE-835', '["https://access.redhat.com/security/cve/CVE-2026-67214","https://github.com/ai/nanoid","https://github.com/ai/nanoid/commit/6ccc67bbaba71d3d77a21d9b636f4171a268ce49","https://github.com/ai/nanoid/commit/e835c9b71eab832bc6106944bdd26ea96cf2c66d","https://github.com/ai/nanoid/pull/600","https://github.com/ai/nanoid/pull/601","https://github.com/ai/nanoid/releases/tag/3.3.16","https://github.com/ai/nanoid/releases/tag/5.1.16","https://nvd.nist.gov/vuln/detail/CVE-2026-67214","https://www.cve.org/CVERecord?id=CVE-2026-67214","https://www.vulncheck.com/advisories/nanoid-before-infinite-loop-via-negative-size-in-non-secure-module"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('c1447a8d-4898-481d-ae12-06e48d1471b9', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'high', 'CVE-2026-73646', 'PostCSS takes a CSS file and provides an API to analyze and modify its rules by transforming the rules into an Abstract Syntax Tree. Prior to 8.5.18, lib/previous-map.js loadMap() passes attacker-controlled sourceMappingURL values to join(dirname(opts.from), annotation), and loadFile() permits traversed or absolute .map paths, allowing untrusted CSS processed without map: false to disclose sourcesContent from arbitrary reachable .map files through result.map. This issue is fixed in version 8.5.18.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-73646', NULL, 'CVE-2026-73646', 'postcss', '8.5.13', '8.5.18', NULL, 'CWE-22', '["https://github.com/postcss/postcss","https://github.com/postcss/postcss/commit/95663d3eb7ba26f4854dd19d3b4f4425760cf56c","https://github.com/postcss/postcss/releases/tag/8.5.18","https://github.com/postcss/postcss/security/advisories/GHSA-r28c-9q8g-f849"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('071fd3cc-8fd9-4700-beff-3d2cade225c9', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'medium', 'CVE-2026-69153', 'PostCSS takes a CSS file and provides an API to analyze and modify its rules by transforming the rules into an Abstract Syntax Tree. Prior to 8.5.19, if from is unset, an attacker can cause PreviousMap.loadFile() to read an unintended source-map file by supplying an absolute or directory-traversal sourceMappingURL. The resulting map’s sources and sourcesContent may then be exposed to the application. This issue is fixed in version 8.5.19.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-69153', NULL, 'CVE-2026-69153', 'postcss', '8.5.13', '8.5.23', 5.3, 'CWE-22', '["https://access.redhat.com/security/cve/CVE-2026-69153","https://github.com/postcss/postcss","https://github.com/postcss/postcss/commit/7beca139e70f9075c6b19700fcb00dd8033e5da8","https://github.com/postcss/postcss/releases/tag/8.5.19","https://github.com/postcss/postcss/security/advisories/GHSA-fxqj-rqcc-2cmp","https://nvd.nist.gov/vuln/detail/CVE-2026-69153","https://www.cve.org/CVERecord?id=CVE-2026-69153"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('c706d4c4-eae9-47b7-94f1-fad220bf891d', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'high', 'CVE-2026-13697', 'undici''s cache interceptor mishandles malformed Cache-Control private directives. In undici 7.0.0 up to before 7.29.0 and 8.0.0 up to before 8.9.0, a response carrying a degenerate qualified private directive, such as private set to an empty value, can be stored in the default shared cache and later served to a different caller with the same cache key, disclosing private response bodies and headers including Set-Cookie. Separately, a Cache-Control header that combines an unqualified private directive with a qualified one triggers an uncaught TypeError in the cache-control parser, which rejects the request and, depending on the consumer''s error handling, can terminate the process. Both issues affect applications using the cache interceptor in shared mode, including the default configuration. The issues are fixed in undici 7.29.0 and 8.9.0.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-13697', NULL, 'CVE-2026-13697', 'undici', '7.28.0', '7.29.0, 8.9.0', 9.1, 'CWE-200', '["https://access.redhat.com/security/cve/CVE-2026-13697","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/4fe5bc5fefe5ac81a200fc8e1cf84b8bf8464451","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-4cwx-7wf7-3272","https://nvd.nist.gov/vuln/detail/CVE-2026-13697","https://www.cve.org/CVERecord?id=CVE-2026-13697"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('528cf889-fa49-4e58-b82a-bf9973f8f927', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'medium', 'CVE-2026-14643', 'undici''s cache interceptor mishandles optional whitespace placed around the equals sign of a qualified no-cache or private Cache-Control directive. In undici from 7.0.0 up to before 7.29.0 and from 8.0.0 up to before 8.9.0, the parser either drops the directive or stores a field name with literal quote characters, so the cache decision fails to recognize the qualification and the response is stored. In shared-cache mode, this lets a response containing one user''s authenticated data be served from cache to a later caller, including an unauthenticated one, when both requests resolve to the same cache key. It affects applications that enable the cache interceptor in shared mode, forward Authorization headers upstream, and receive cacheable responses with qualified directives padded with whitespace around the equals sign. This is the whitespace-around-equals variant that the fix for CVE-2026-9678 did not normalize, and it is fixed in undici 7.29.0 and 8.9.0.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-14643', NULL, 'CVE-2026-14643', 'undici', '7.28.0', '7.29.0, 8.9.0', 7.5, 'CWE-436', '["https://access.redhat.com/security/cve/CVE-2026-14643","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/85a240551c9feb8b8a0ecc56c84b2b3015add8a9","https://github.com/nodejs/undici/commit/cb105d7c79069150982fa11acada0dd94a60dbbc","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-jr45-8vmc-qm54","https://nvd.nist.gov/vuln/detail/CVE-2026-14643","https://www.cve.org/CVERecord?id=CVE-2026-14643"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('307e8893-f0cb-465a-a826-0e8071354fd7', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'medium', 'CVE-2026-15157', 'undici does not validate the type property of a duck-typed blob-like request body before using it as the Content-Type header on the HTTP/1.1 dispatcher. In undici before 6.28.0, from 7.0.0 up to before 7.29.0, and from 8.0.0 up to before 8.9.0, an application that passes a hand-rolled blob-like body (via request, stream, pipeline, or dispatch) whose type is derived from untrusted input allows an attacker to inject CRLF sequences and append arbitrary HTTP headers, potentially smuggling a second request past the upstream. Native Blob objects are safe because their constructor strips CRLF from the type, and fetch is unaffected because it validates headers, but ecosystem libraries that build duck-typed blob shapes from user input can reach the vulnerable path. This is the same defect class as CVE-2022-35948 and CVE-2026-1527, on a header sink that the earlier fixes did not cover. The issue is fixed in undici 6.28.0, 7.29.0, and 8.9.0.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-15157', NULL, 'CVE-2026-15157', 'undici', '7.28.0', '6.28.0, 7.29.0, 8.9.0', 5.4, 'CWE-93', '["https://access.redhat.com/security/cve/CVE-2026-15157","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/33928bc24f742ea8422ed90d17f2e0cc83e4d09d","https://github.com/nodejs/undici/commit/740a0b7c173cb4a83a5b693e96e8f3a116cfc400","https://github.com/nodejs/undici/commit/7d3cf924c262c486bc77f951348f4e5c847b7b42","https://github.com/nodejs/undici/releases/tag/v6.28.0","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-m8rv-5g2x-5cg5","https://nvd.nist.gov/vuln/detail/CVE-2026-15157","https://www.cve.org/CVERecord?id=CVE-2026-15157"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('cf739495-83cb-49c5-9474-c1dd175091c3', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'medium', 'CVE-2026-16728', 'undici''s retry interceptor can deliver a response whose body length does not match the Content-Length header exposed to the application after a retry or resume of a partial response. In undici before 6.28.0, from 7.0.0 up to before 7.29.0, and from 8.0.0 up to before 8.9.0, a malicious or faulty upstream can return a partial response with a mismatched framing header, close the socket early, and have the retry interceptor assemble a body of a different length while the original Content-Length stays attached. Applications that use the retry interceptor and forward upstream headers and bodies downstream, such as proxies or gateways, may then emit an invalid HTTP response with a stale Content-Length, leading to downstream response desynchronization, connection hangs, or response corruption. Exploitation requires the retry interceptor enabled, an upstream returning a mismatched partial response, and a downstream forwarder that does not remove or recalculate Content-Length. The issue is fixed in undici 6.28.0, 7.29.0, and 8.9.0.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-16728', NULL, 'CVE-2026-16728', 'undici', '7.28.0', '6.28.0, 7.29.0, 8.9.0', 6.5, 'CWE-444', '["https://access.redhat.com/security/cve/CVE-2026-16728","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/1b5a5312c3a7d7a30c31bf0d000b39a8a2531e1c","https://github.com/nodejs/undici/commit/2b3f749336d356bbbc50192f87f6cf7bc714721a","https://github.com/nodejs/undici/commit/4a9dafb16ff43880cf590e6d9c2aeee25fbff6d7","https://github.com/nodejs/undici/commit/4fd5a0c61e627f928b7003adc4ffe1e55ec63420","https://github.com/nodejs/undici/commit/cba3a52ac2e7abcc4e656d82af8579ea82c2bb9e","https://github.com/nodejs/undici/commit/e11a68ed4ff345c79402476f7a00d473443e318d","https://github.com/nodejs/undici/releases/tag/v6.28.0","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-8xcm-r25x-g524","https://hackerone.com/reports/3828685","https://nvd.nist.gov/vuln/detail/CVE-2026-16728","https://www.cve.org/CVERecord?id=CVE-2026-16728"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('07f4db91-1ecc-4633-b649-0c17ada2cbc7', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'medium', 'CVE-2026-16729', 'undici''s setCookie function does not fully sanitize cookie attributes. In undici before 6.28.0, from 7.0.0 up to before 7.29.0, and from 8.0.0 up to before 8.9.0, a domain value is not checked for semicolons and entries in the unparsed array are not sanitized, so attacker-influenced input can inject additional cookie attributes. For example, a domain value containing a semicolon can append attributes such as SameSite, and an unparsed entry can inject attributes such as HttpOnly, without the caller setting them. Applications that pass user-controlled input to these fields, such as multi-tenant or reverse-proxy servers that scope session cookies to a tenant-supplied domain, can have SameSite CSRF protections bypassed, or the Secure, HttpOnly, and SameSite attributes forced, stripped, or overridden. The issue is fixed in undici 6.28.0, 7.29.0, and 8.9.0.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-16729', NULL, 'CVE-2026-16729', 'undici', '7.28.0', '6.28.0, 7.29.0, 8.9.0', 6.5, 'CWE-74', '["https://access.redhat.com/security/cve/CVE-2026-16729","https://cna.openjsf.org/security-advisories.html","https://github.com/nodejs/undici","https://github.com/nodejs/undici/commit/10d93fc332f2c8c161982dec3833201de29891b5","https://github.com/nodejs/undici/commit/3bf91ddb493e853957f3a58e155326a668ab8aef","https://github.com/nodejs/undici/commit/af7484043ee075a6f216da0ad77e1dac55199235","https://github.com/nodejs/undici/releases/tag/v6.28.0","https://github.com/nodejs/undici/releases/tag/v7.29.0","https://github.com/nodejs/undici/releases/tag/v8.9.0","https://github.com/nodejs/undici/security/advisories/GHSA-v3r7-h72x-cjcm","https://nvd.nist.gov/vuln/detail/CVE-2026-16729","https://www.cve.org/CVERecord?id=CVE-2026-16729"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('6d7ea7f9-64c1-4da9-aa04-66b8a2d17012', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '5aaeec76-38a6-4c93-bd14-d828cd473e2e', 'vulnerability', 'high', 'CVE-2026-55553', 'urllib is an HTTP client for Node.js that supports authentication, redirects, timeouts, and other request features. Prior to 4.9.1 and 2.44.1, urllib follows redirects through followRedirect but reuses caller-supplied options across origins. In src/HttpClient.ts, #requestInternal recursively calls this.#requestInternal(nextUrl.href, options, requestContext), causing options.headers and auth or digestAuth values to be reused when the redirect target has a different scheme, host, or port. Authorization, Cookie, Proxy-Authorization, x-api-key, x-auth-token, and x-access-token can therefore be sent to an attacker-controlled redirected origin, exposing credentials intended for the original origin and potentially allowing reuse against the original partner API or related services. No user interaction is required. This issue is fixed in versions 2.44.1 and 4.9.1.', 'package-lock.json', 0, NULL, NULL, 'CVE-2026-55553', NULL, 'CVE-2026-55553', 'urllib', '4.9.0', '4.9.1, 2.44.1', NULL, 'CWE-200', '["https://github.com/node-modules/urllib","https://github.com/node-modules/urllib/commit/7c86c465883ebd3dea5109c87d7bbe3b00960a16","https://github.com/node-modules/urllib/commit/811a8d56e64e540bf6a19bf8b3737692f05d5c46","https://github.com/node-modules/urllib/pull/812","https://github.com/node-modules/urllib/pull/813","https://github.com/node-modules/urllib/releases/tag/v2.44.1","https://github.com/node-modules/urllib/releases/tag/v4.9.1","https://github.com/node-modules/urllib/security/advisories/GHSA-hq3h-g68c-hp78"]'::jsonb, NULL, 'open', to_timestamp(1787726235848 / 1000.0), to_timestamp(1787726235848 / 1000.0)),
  ('4677dbe0-d7f7-42c1-a266-ab2ef02d2700', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'vulnerability', 'high', 'Outdated OpenSSL version with known CVEs', 'The project vendors OpenSSL 1.1.1k which has multiple CVEs including CVE-2022-0778 (infinite loop in BN_mod_sqrt) and CVE-2022-1292 (c_rehash script command injection). Should upgrade to OpenSSL 1.1.1t+ or 3.0.x.', 'docker/Dockerfile', 12, NULL, NULL, 'CVE-2022-0778', NULL, 'CVE-2022-0778', 'openssl', '1.1.1k', '1.1.1t', NULL, NULL, '[]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade openssl to 1.1.1t"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('5fb94276-69b5-4a14-accf-851cd0b21957', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'vulnerability', 'medium', 'Nimble dependency ''nimcrypto'' has timing attack vulnerability', 'The nimcrypto library version 0.3.0 used for HMAC verification is vulnerable to timing attacks in constant-time comparison. An attacker could forge valid signatures through side-channel analysis.', 'nimble.lock', 45, NULL, NULL, 'CVE-2021-32675', NULL, 'CVE-2021-32675', 'nimcrypto', '0.3.0', '0.4.1', NULL, NULL, '[]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade nimcrypto to 0.4.1"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('b00953eb-ae55-432f-809e-0980624da321', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'secret', 'critical', 'Twitter API bearer token hardcoded in configuration example', 'A valid Twitter API v2 bearer token is committed in the example configuration file. This token could be used to make authenticated requests to Twitter''s API on behalf of the application owner.', 'nitter.example.conf', 23, NULL, NULL, 'gitleaks-twitter-bearer-token', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('01d90c2a-5bf1-4829-9e54-6db43d02c313', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'secret', 'high', 'Redis password exposed in docker-compose.yml', 'The docker-compose file contains a hardcoded Redis password ''changeme123'' which is used in production deployments. This allows unauthorized access to Redis instance if exposed.', 'docker-compose.yml', 18, NULL, NULL, 'gitleaks-generic-password', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('bbd3c7b7-398b-4ebf-9e0d-3abe2f3fc7fa', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'security_issue', 'high', 'Server-Side Request Forgery (SSRF) in media proxy endpoint', 'The /pic/media proxy endpoint accepts arbitrary URLs without validation, allowing attackers to make requests to internal services (localhost, metadata endpoints, internal networks). No allowlist or private IP blocking is implemented.', 'src/nitter/routes.nim', 312, NULL, NULL, 'semgrep-nim-ssrf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('34b7af6d-19c9-43ea-8ad1-357878e9565b', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'security_issue', 'medium', 'Cross-Site Scripting (XSS) via user-controlled profile fields', 'User profile fields (name, bio, location) are rendered without proper escaping in the HTML templates. An attacker could inject JavaScript through crafted profile data when viewed by other users.', 'src/nitter/templates/profile.nim', 67, NULL, NULL, 'semgrep-nim-xss', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('e3798c10-487b-4b99-8a13-845d37f19dc0', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'security_issue', 'medium', 'Missing rate limiting on API endpoints', 'The guest token generation and search endpoints lack rate limiting, allowing automated scraping and brute-force attacks. This could lead to IP bans from Twitter and service degradation.', 'src/nitter/routes.nim', 145, NULL, NULL, 'semgrep-missing-rate-limit', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('a42ec795-53a9-4f4a-a158-15a34ba1f2cd', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'misconfiguration', 'medium', 'Debug mode enabled in production Docker image', 'The Dockerfile sets NIM_DEBUG=1 which enables debug logging and stack traces in production. This leaks internal application structure and could aid attackers in crafting exploits.', 'docker/Dockerfile', 28, NULL, NULL, 'debug-enabled-prod', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('23dc1128-713d-4d32-9a16-571748f37afc', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'misconfiguration', 'low', 'Insecure cookie settings - missing Secure and HttpOnly flags', 'Session cookies are set without Secure and HttpOnly flags, making them accessible to JavaScript and transmissible over HTTP. This increases risk of session hijacking via XSS or MITM.', 'src/nitter/middleware.nim', 89, NULL, NULL, 'insecure-cookie-config', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('4392ab63-afe9-416c-9bad-6db0061e34f6', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'vulnerability', 'medium', 'SQLite database file world-readable in container', 'The SQLite database file permissions are set to 644, allowing any user in the container to read guest tokens and cached data. Should be restricted to 600.', 'docker/entrypoint.sh', 15, NULL, NULL, 'insecure-file-permissions', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('2d2b4476-ce59-4886-9e09-9f7d5c3a0cdc', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'security_issue', 'low', 'Information disclosure via error messages', 'Detailed Nim stack traces are returned to clients on internal server errors, revealing file paths, function names, and code structure. Should use generic error pages in production.', 'src/nitter/error.nim', 34, NULL, NULL, 'info-disclosure-stacktrace', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('7acef6cb-a72a-40bf-a92d-6e75deccf5b6', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'vulnerability', 'high', 'Dependency ''libxml2'' version 2.9.10 has multiple CVEs', 'The vendored libxml2 2.9.10 contains CVE-2022-23308 (use-after-free in xmlSchemaRun), CVE-2022-29824 (buffer overflow in xmlEncodeEntitiesInternal), and others. Used for HTML parsing.', 'docker/Dockerfile', 15, NULL, NULL, 'CVE-2022-23308', NULL, 'CVE-2022-23308', 'libxml2', '2.9.10', '2.9.14', NULL, NULL, '[]'::jsonb, '{"available":true,"type":"upgrade","description":"Upgrade libxml2 to 2.9.14"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('837d1e41-1ce3-43a9-979a-750942e23735', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'secret', 'medium', 'Generic API key pattern found in test fixtures', 'Test fixture files contain what appears to be a real API key pattern (sk_live_...) in mock response data. While likely a placeholder, it matches live secret patterns and could be a leaked key.', 'tests/fixtures/api_responses.json', 12, NULL, NULL, 'gitleaks-stripe-api-key', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, NULL, 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('e2b17f12-78d2-43a6-9eac-24b7ce6cb64c', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'misconfiguration', 'low', 'Content Security Policy missing frame-ancestors directive', 'The CSP header lacks frame-ancestors directive, allowing the site to be embedded in iframes on arbitrary domains. This enables clickjacking attacks.', 'src/nitter/middleware.nim', 102, NULL, NULL, 'csp-missing-frame-ancestors', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('d0d3ba40-764f-442b-81a8-0be2717aab2d', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', '8c1571ed-3fa8-487b-9a3e-135677fbc63a', 'security_issue', 'info', 'Use of deprecated Twitter API v1.1 endpoints', 'The codebase still references Twitter API v1.1 endpoints (e.g., statuses/user_timeline) which are deprecated and may stop working. Migration to API v2 is recommended for long-term stability.', 'src/nitter/twitter.nim', 267, NULL, NULL, 'deprecated-api-usage', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, '{"available":true,"type":"patch","description":"AI can generate a patch for this finding"}', 'open', to_timestamp(1788091334457 / 1000.0), to_timestamp(1788091334457 / 1000.0)),
  ('acf3423d-2a66-4865-993d-dd1ac0ddad16', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b05d1fbf-04d3-4b27-bb4f-1dd133381200', 'vulnerability', 'critical', 'CVE-2022-3786', 'OpenSSL 3.0.0-3.0.6: X.509 email address buffer overflow in name constraint checking', NULL, NULL, NULL, NULL, NULL, NULL, 'CVE-2022-3786', 'openssl', '1.1.1k', '3.0.7', NULL, NULL, '["https://nvd.nist.gov/vuln/detail/CVE-2022-3786","https://www.openssl.org/news/secadv/20221101.txt"]'::jsonb, NULL, 'open', to_timestamp(1788091635182 / 1000.0), to_timestamp(1788091635182 / 1000.0)),
  ('866d8b3e-5f76-4325-90c2-7674d817ffb5', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b05d1fbf-04d3-4b27-bb4f-1dd133381200', 'vulnerability', 'high', 'CVE-2022-3602', 'OpenSSL 3.0.0-3.0.6: X.509 email address variable length buffer overflow', NULL, NULL, NULL, NULL, NULL, NULL, 'CVE-2022-3602', 'openssl', '1.1.1k', '3.0.7', NULL, NULL, '["https://nvd.nist.gov/vuln/detail/CVE-2022-3602","https://www.openssl.org/news/secadv/20221101.txt"]'::jsonb, NULL, 'open', to_timestamp(1788091635182 / 1000.0), to_timestamp(1788091635182 / 1000.0)),
  ('e260b8d8-4c92-4a74-bff8-e25605a0ec6c', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b05d1fbf-04d3-4b27-bb4f-1dd133381200', 'vulnerability', 'high', 'CVE-2021-3711', 'OpenSSL 1.1.1k: SM2 decryption buffer overflow', NULL, NULL, NULL, NULL, NULL, NULL, 'CVE-2021-3711', 'openssl', '1.1.1k', '1.1.1l', NULL, NULL, '["https://nvd.nist.gov/vuln/detail/CVE-2021-3711"]'::jsonb, NULL, 'open', to_timestamp(1788091635182 / 1000.0), to_timestamp(1788091635182 / 1000.0)),
  ('a693a245-0f51-41db-9265-cb0bc62d76b4', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b05d1fbf-04d3-4b27-bb4f-1dd133381200', 'vulnerability', 'high', 'CVE-2021-3712', 'OpenSSL 1.1.1k: Read buffer overrun in ASN.1 string processing', NULL, NULL, NULL, NULL, NULL, NULL, 'CVE-2021-3712', 'openssl', '1.1.1k', '1.1.1l', NULL, NULL, '["https://nvd.nist.gov/vuln/detail/CVE-2021-3712"]'::jsonb, NULL, 'open', to_timestamp(1788091635182 / 1000.0), to_timestamp(1788091635182 / 1000.0)),
  ('a1c0455f-48a0-46f3-95b9-f30539756db0', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b05d1fbf-04d3-4b27-bb4f-1dd133381200', 'vulnerability', 'medium', 'CVE-2022-37434', 'zlib 1.2.11: Heap-based buffer overflow in inflate() via a large gzip header extra field', NULL, NULL, NULL, NULL, NULL, NULL, 'CVE-2022-37434', 'zlib', '1.2.11', '1.2.13', NULL, NULL, '["https://nvd.nist.gov/vuln/detail/CVE-2022-37434"]'::jsonb, NULL, 'open', to_timestamp(1788091635182 / 1000.0), to_timestamp(1788091635182 / 1000.0))
