  ('2368d266-c8c9-4c05-bebc-3dcf95fd6d2b', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'b05d1fbf-04d3-4b27-bb4f-1dd133381200', 'vulnerability', 'medium', 'CVE-2022-23852', 'Expat (XML parser) <= 2.4.7: Stack exhaustion in XML_ParseBuffer via deeply nested entities', NULL, NULL, NULL, NULL, NULL, NULL, 'CVE-2022-23852', 'expat', '2.4.1', '2.4.8', NULL, NULL, '["https://nvd.nist.gov/vuln/detail/CVE-2022-23852"]'::jsonb, NULL, 'open', to_timestamp(1788091635182 / 1000.0), to_timestamp(1788091635182 / 1000.0)),
