INSERT INTO public.findings (id, user_id, scan_id, type, severity, title, description, file, line, column_index, code, rule_id, rule_name, cve, package, installed_version, fixed_version, cvss_score, cwe, reference_urls, remediation, status, created_at, updated_at) VALUES
  ('8a29dd25-7ec2-420f-b31a-a27e923a0fed', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'd65621c3-708a-40c5-8dcd-5cd80a3026e8', 'vulnerability', 'medium', 'CVE-2023-45857', 'An issue discovered in Axios 1.5.1 inadvertently reveals the confidential XSRF-TOKEN stored in cookies by including it in the HTTP header X-XSRF-TOKEN for every request made to any host allowing attackers to view sensitive information.', 'pnpm-lock.yaml', 0, NULL, NULL, 'CVE-2023-45857', NULL, 'CVE-2023-45857', 'axios', '0.21.4', '1.6.0, 0.28.0', 6.5, 'CWE-352', '["https://access.redhat.com/security/cve/CVE-2023-45857","https://github.com/axios/axios","https://github.com/axios/axios/commit/2755df562b9c194fba6d8b609a383443f6a6e967","https://github.com/axios/axios/commit/96ee232bd3ee4de2e657333d4d2191cd389e14d0","https://github.com/axios/axios/issues/6006","https://github.com/axios/axios/issues/6022","https://github.com/axios/axios/pull/6028","https://github.com/axios/axios/pull/6091","https://github.com/axios/axios/releases/tag/v0.28.0","https://github.com/axios/axios/releases/tag/v1.6.0","https://nvd.nist.gov/vuln/detail/CVE-2023-45857","https://security.netapp.com/advisory/ntap-20240621-0006","https://security.netapp.com/advisory/ntap-20240621-0006/","https://security.snyk.io/vuln/SNYK-JS-AXIOS-6032459","https://www.cve.org/CVERecord?id=CVE-2023-45857"]'::jsonb, NULL, 'open', to_timestamp(1788093695163 / 1000.0), to_timestamp(1788093695163 / 1000.0)),
  ('e3562a77-e260-42ff-bbba-e718d6c7d4bf', 'ba971bfd-e5de-4d96-b596-a236cfb067f6', 'd65621c3-708a-40c5-8dcd-5cd80a3026e8', 'vulnerability', 'medium', 'CVE-2025-62718', 'Axios is a promise based HTTP client for the browser and Node.js. Prior to 1.15.0 and 0.31.0, Axios does not correctly handle hostname normalization when checking NO_PROXY rules. Requests to loopback addresses like localhost. (with a trailing dot) or [::1] (IPv6 literal) skip NO_PROXY matching and go through the configured proxy. This goes against what developers expect and lets attackers force requests through a proxy, even if NO_PROXY is set up to protect loopback or internal services. This issue leads to the possibility of proxy bypass and SSRF vulnerabilities allowing attackers to reach sensitive loopback or internal services despite the configured protections. This vulnerability is fixed in 1.15.0 and 0.31.0.', 'pnpm-lock.yaml', 0, NULL, NULL, 'CVE-2025-62718', NULL, 'CVE-2025-62718', 'axios', '0.21.4', '1.15.0, 0.31.0', 9.9, 'CWE-441', '["https://access.redhat.com/errata/RHSA-2026:10175","https://access.redhat.com/errata/RHSA-2026:13571","https://access.redhat.com/errata/RHSA-2026:13826","https://access.redhat.com/errata/RHSA-2026:14937","https://access.redhat.com/errata/RHSA-2026:16874","https://access.redhat.com/errata/RHSA-2026:17657","https://access.redhat.com/errata/RHSA-2026:17699","https://access.redhat.com/errata/RHSA-2026:19375","https://access.redhat.com/errata/RHSA-2026:19712","https://access.redhat.com/errata/RHSA-2026:20889","https://access.redhat.com/errata/RHSA-2026:20938","https://access.redhat.com/errata/RHSA-2026:21017","https://access.redhat.com/errata/RHSA-2026:22465","https://access.redhat.com/errata/RHSA-2026:22629","https://access.redhat.com/errata/RHSA-2026:22840","https://access.redhat.com/errata/RHSA-2026:23361","https://access.redhat.com/errata/RHSA-2026:24471","https://access.redhat.com/errata/RHSA-2026:24761","https://access.redhat.com/errata/RHSA-2026:24766","https